-- AIPE Community interaction: comments with one level of replies, reports,
-- full-text search and links from contributions to Academy knowledge topics.
--
-- Knowledge topics mirror the ids of the AIPE Academy knowledge graph
-- (_data/knowledge_graph.yml). They are loaded from supabase/knowledge_topics.sql
-- (generated by tools/community_topics.py) and are read-only to members.
-- Community links to topics live in contribution_topics, never in Academy data;
-- only moderators can mark a link as curated.

-- ── Search ─────────────────────────────────────────────────────────────────
alter table public.contributions
  add column search tsvector generated always as (
    setweight(to_tsvector('simple', coalesce(title, '')), 'A') ||
    setweight(to_tsvector('simple', coalesce(summary, '')), 'B') ||
    to_tsvector('simple', coalesce(hypothesis, '') || ' ' || coalesce(body_md, '') || ' ' ||
                          coalesce(limitations, '') || ' ' || coalesce(licence, ''))
  ) stored;
create index contributions_search_idx on public.contributions using gin (search);
-- search is derived, never written by clients (no insert/update grant exists).

-- ── Knowledge topics ───────────────────────────────────────────────────────
create table public.knowledge_topics (
  id       text primary key check (id ~ '^[a-z]+\.[a-z0-9-]+$'),
  subject  text not null,
  title_en text not null,
  title_zh text not null,
  retired  boolean not null default false  -- no longer in the Academy graph; existing links are kept
);
alter table public.knowledge_topics enable row level security;
revoke all on public.knowledge_topics from anon, authenticated;
grant select on public.knowledge_topics to anon, authenticated;
create policy "Knowledge topics are public" on public.knowledge_topics for select using (true);

create table public.contribution_topics (
  contribution_id uuid not null references public.contributions (id) on delete cascade,
  topic_id        text not null references public.knowledge_topics (id) on update cascade,
  curated         boolean not null default false,
  curated_by      uuid references public.profiles (id) on delete set null,
  curated_at      timestamptz,
  created_at      timestamptz not null default now(),
  primary key (contribution_id, topic_id)
);
create index contribution_topics_topic_idx on public.contribution_topics (topic_id);

create function public.check_contribution_topic() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  target uuid := coalesce(new.contribution_id, old.contribution_id);
begin
  if tg_op = 'INSERT' then
    if exists (select 1 from public.knowledge_topics where id = new.topic_id and retired) then
      raise exception 'topic_retired' using errcode = '22023';
    end if;
    if (select count(*) from public.contribution_topics where contribution_id = new.contribution_id) >= 8 then
      raise exception 'too_many_topics' using errcode = '22023';
    end if;
  end if;
  -- Changing topics is a content edit: republication needs a fresh review.
  update public.contributions set edited_at = now() where id = target;
  return coalesce(new, old);
end;
$$;
create trigger contribution_topics_check before insert or delete on public.contribution_topics
  for each row execute function public.check_contribution_topic();

alter table public.contribution_topics enable row level security;
revoke all on public.contribution_topics from anon, authenticated;
grant select on public.contribution_topics to anon, authenticated;
grant insert (contribution_id, topic_id) on public.contribution_topics to authenticated;
grant delete on public.contribution_topics to authenticated;

-- Visible whenever the contribution is visible to the caller (RLS on
-- contributions applies inside the subquery).
create policy "Topic links follow their contribution" on public.contribution_topics for select
  using (exists (select 1 from public.contributions c where c.id = contribution_id));
create policy "Authors link topics while editing" on public.contribution_topics for insert to authenticated
  with check (exists (select 1 from public.contributions c where c.id = contribution_id and c.author_id = auth.uid()
                      and c.status in ('draft', 'changes_requested', 'unpublished')));
create policy "Authors unlink topics while editing" on public.contribution_topics for delete to authenticated
  using (not curated and exists (select 1 from public.contributions c where c.id = contribution_id and c.author_id = auth.uid()
                                 and c.status in ('draft', 'changes_requested', 'unpublished')));

-- Moderators mark a published contribution's topic link as a curated
-- resource candidate for the official Academy views (see docs/community/moderation.md).
create function public.curate_topic(p_contribution uuid, p_topic text, p_curated boolean)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_moderator() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_curated and not exists (select 1 from public.contributions where id = p_contribution and status = 'published') then
    raise exception 'not_published' using errcode = 'P0001';
  end if;
  update public.contribution_topics
     set curated = p_curated,
         curated_by = case when p_curated then auth.uid() end,
         curated_at = case when p_curated then now() end
   where contribution_id = p_contribution and topic_id = p_topic;
  if not found then
    raise exception 'not_found' using errcode = 'P0002';
  end if;
  perform public.log_moderation('contribution', p_contribution, case when p_curated then 'curate_topic' else 'uncurate_topic' end,
                                null, p_topic, null);
end;
$$;

-- Curated links on published contributions: the input to the documented,
-- administrator-run promotion into _data/knowledge_graph_resources.yml.
create view public.curated_topic_resources with (security_invoker = true) as
  select t.topic_id, c.slug, c.type, c.title, c.lang, t.curated_at
    from public.contribution_topics t
    join public.contributions c on c.id = t.contribution_id
   where t.curated and c.status = 'published';
grant select on public.curated_topic_resources to anon, authenticated;

-- ── Comments ───────────────────────────────────────────────────────────────
create table public.comments (
  id              uuid primary key default gen_random_uuid(),
  contribution_id uuid not null references public.contributions (id) on delete cascade,
  author_id       uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  parent_id       uuid references public.comments (id) on delete set null,
  body            text not null check (char_length(body) <= 4000),
  status          text not null default 'visible' check (status in ('visible', 'hidden', 'deleted')),
  created_at      timestamptz not null default now(),
  edited_at       timestamptz
);
create index comments_contribution_idx on public.comments (contribution_id, created_at);
create index comments_author_idx on public.comments (author_id, created_at desc);

create function public.prepare_comment() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  parent public.comments;
begin
  if tg_op = 'INSERT' then
    new.body := btrim(new.body);
    if char_length(new.body) < 2 then
      raise exception 'comment_empty' using errcode = '22023';
    end if;
    if not exists (select 1 from public.contributions where id = new.contribution_id and status = 'published') then
      raise exception 'not_published' using errcode = 'P0001';
    end if;
    if new.parent_id is not null then
      select * into parent from public.comments where id = new.parent_id;
      -- One level of replies, within the same discussion, to a visible comment.
      if not found or parent.contribution_id <> new.contribution_id or parent.parent_id is not null or parent.status <> 'visible' then
        raise exception 'invalid_parent' using errcode = '22023';
      end if;
    end if;
    if (select count(*) from public.comments where author_id = new.author_id and created_at > now() - interval '10 minutes') >= 10
       or (select count(*) from public.comments where author_id = new.author_id and created_at > now() - interval '1 day') >= 100 then
      raise exception 'rate_limited' using errcode = 'P0001';
    end if;
  elsif new.body is distinct from old.body then
    new.body := btrim(new.body);
    if new.status = 'visible' and char_length(new.body) < 2 then
      raise exception 'comment_empty' using errcode = '22023';
    end if;
    new.edited_at := now();
  end if;
  -- Link-heavy comments are a common spam pattern.
  if (select count(*) from regexp_matches(new.body, 'https?://', 'g')) > 5 then
    raise exception 'too_many_links' using errcode = '22023';
  end if;
  return new;
end;
$$;
create trigger comments_prepare before insert or update on public.comments
  for each row execute function public.prepare_comment();

alter table public.comments enable row level security;
revoke all on public.comments from anon, authenticated;
grant select on public.comments to anon, authenticated;
grant insert (contribution_id, parent_id, body) on public.comments to authenticated;
grant update (body) on public.comments to authenticated;

-- Deleted comments stay as placeholders so replies keep their context;
-- hidden comments are visible only to their author and moderators.
create policy "Comments on published work are public" on public.comments for select
  using (
    public.is_moderator()
    or ((status in ('visible', 'deleted') or author_id = auth.uid())
        and exists (select 1 from public.contributions c where c.id = contribution_id and c.status = 'published'))
  );
create policy "Members comment as themselves" on public.comments for insert to authenticated
  with check (author_id = auth.uid() and status = 'visible');
create policy "Authors edit their visible comments" on public.comments for update to authenticated
  using (author_id = auth.uid() and status = 'visible') with check (author_id = auth.uid());

create function public.delete_comment(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  update public.comments set status = 'deleted', body = ''
   where id = p_id and author_id = auth.uid() and status <> 'deleted';
  if not found then
    raise exception 'not_found' using errcode = 'P0002';
  end if;
end;
$$;

create function public.moderate_comment(p_id uuid, p_action text, p_note text default null) returns text
language plpgsql security definer set search_path = public as $$
declare
  c public.comments;
  target text;
begin
  if not public.is_moderator() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  select * into c from public.comments where id = p_id for update;
  if not found then
    raise exception 'not_found' using errcode = 'P0002';
  end if;
  target := case when p_action = 'hide' and c.status = 'visible' then 'hidden'
                 when p_action = 'restore' and c.status = 'hidden' then 'visible' end;
  if target is null then
    raise exception 'invalid_transition' using errcode = 'P0001';
  end if;
  if p_action = 'hide' and coalesce(btrim(p_note), '') = '' then
    raise exception 'note_required' using errcode = 'P0001';
  end if;
  update public.comments set status = target where id = p_id;
  perform public.log_moderation('comment', p_id, p_action, c.status, target, p_note);
  return target;
end;
$$;

-- ── Reports ────────────────────────────────────────────────────────────────
create table public.reports (
  id          uuid primary key default gen_random_uuid(),
  reporter_id uuid default auth.uid() references public.profiles (id) on delete set null,
  target_type text not null check (target_type in ('contribution', 'comment')),
  target_id   uuid not null,
  reason      text not null check (reason in ('spam', 'abuse', 'misleading', 'copyright', 'unsafe', 'other')),
  details     text not null default '' check (char_length(details) <= 1000),
  status      text not null default 'open' check (status in ('open', 'actioned', 'dismissed')),
  created_at  timestamptz not null default now(),
  resolved_at timestamptz,
  resolved_by uuid references public.profiles (id) on delete set null
);
create unique index reports_once_idx on public.reports (reporter_id, target_type, target_id) where status = 'open';
create index reports_open_idx on public.reports (status, created_at);

create function public.check_report() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.target_type = 'contribution'
     and not exists (select 1 from public.contributions where id = new.target_id and status = 'published') then
    raise exception 'not_found' using errcode = 'P0002';
  end if;
  if new.target_type = 'comment'
     and not exists (select 1 from public.comments where id = new.target_id and status = 'visible') then
    raise exception 'not_found' using errcode = 'P0002';
  end if;
  if (select count(*) from public.reports where reporter_id = new.reporter_id and created_at > now() - interval '1 day') >= 20 then
    raise exception 'rate_limited' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
create trigger reports_check before insert on public.reports
  for each row execute function public.check_report();

alter table public.reports enable row level security;
revoke all on public.reports from anon, authenticated;
grant select on public.reports to authenticated;
grant insert (target_type, target_id, reason, details) on public.reports to authenticated;
create policy "Moderators see reports; reporters see their own" on public.reports for select to authenticated
  using (public.is_moderator() or reporter_id = auth.uid());
create policy "Members file reports as themselves" on public.reports for insert to authenticated
  with check (reporter_id = auth.uid() and status = 'open');

create function public.resolve_report(p_id uuid, p_outcome text, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare
  r public.reports;
begin
  if not public.is_moderator() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_outcome not in ('actioned', 'dismissed') then
    raise exception 'invalid_transition' using errcode = 'P0001';
  end if;
  select * into r from public.reports where id = p_id and status = 'open' for update;
  if not found then
    raise exception 'not_found' using errcode = 'P0002';
  end if;
  update public.reports set status = p_outcome, resolved_at = now(), resolved_by = auth.uid() where id = p_id;
  perform public.log_moderation('report', p_id, p_outcome, 'open', p_outcome, p_note);
end;
$$;

revoke all on function public.curate_topic(uuid, text, boolean), public.delete_comment(uuid),
  public.moderate_comment(uuid, text, text), public.resolve_report(uuid, text, text) from public, anon;
grant execute on function public.curate_topic(uuid, text, boolean), public.delete_comment(uuid),
  public.moderate_comment(uuid, text, text), public.resolve_report(uuid, text, text) to authenticated;
